import { z } from 'zod';
import type { Point } from '../../types';

const PartySchema = z.object({
  abbrev: z.string(),
  winProbability: z.number().min(0).max(1),
  seats: z.number().optional(),
});

const OverviewSchema = z.object({
  forecast: z.object({ parties: z.array(PartySchema), updatedAt: z.string().optional() }),
  timeseries: z.array(z.object({ date: z.string(), parties: z.array(PartySchema) })).default([]),
});

export interface DdhqForecast {
  house: number;
  senate: number;
  /** "DEM Senate and DEM House" as published on the overview page. */
  sweep: number | null;
  updatedAt: string | null;
  houseHistory: Point[];
  senateHistory: Point[];
}

/**
 * Extracts the balanced JSON array that follows `"key":` in `text`.
 * The page embeds data in a Next.js RSC payload, not a public API.
 */
export function extractJsonArray(text: string, key: string): unknown {
  const start = text.indexOf(`"${key}":[`);
  if (start < 0) throw new Error(`"${key}" not found`);
  const open = text.indexOf('[', start);
  let depth = 0;
  let inString = false;
  for (let i = open; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      if (ch === '\\') i++;
      else if (ch === '"') inString = false;
    } else if (ch === '"') inString = true;
    else if (ch === '[' || ch === '{') depth++;
    else if (ch === ']' || ch === '}') {
      depth--;
      if (depth === 0) return JSON.parse(text.slice(open, i + 1));
    }
  }
  throw new Error(`unterminated "${key}" array`);
}

const demProb = (parties: z.infer<typeof PartySchema>[]): number | undefined =>
  parties.find((p) => p.abbrev === 'DEM')?.winProbability;

const toPoints = (ts: z.infer<typeof OverviewSchema>['timeseries']): Point[] =>
  ts.flatMap((e) => {
    const p = demProb(e.parties);
    const t = Date.parse(`${e.date}T12:00:00Z`) / 1000;
    return p === undefined || Number.isNaN(t) ? [] : [{ t, p }];
  });

/** Parses the DDHQ forecast overview page HTML. Chambers are identified by total seats (435 / 100). */
export function parseDdhq(html: string): DdhqForecast {
  const unescaped = html.replace(/\\"/g, '"');
  const overviews = z.array(OverviewSchema).parse(extractJsonArray(unescaped, 'overviews'));

  const byChamber = (total: number) =>
    overviews.find((o) => o.forecast.parties.reduce((s, p) => s + (p.seats ?? 0), 0) === total);
  const house = byChamber(435);
  const senate = byChamber(100);
  const houseP = house && demProb(house.forecast.parties);
  const senateP = senate && demProb(senate.forecast.parties);
  if (houseP === undefined || senateP === undefined) throw new Error('chamber forecasts not found');

  const combo = /DEM Senate and DEM House<\/h3>\s*<span[^>]*>\s*([\d.]+)\s*(?:<!-- -->)?\s*%/.exec(html);
  const sweep = combo?.[1] ? Number(combo[1]) / 100 : null;

  return {
    house: houseP,
    senate: senateP,
    sweep: sweep !== null && sweep >= 0 && sweep <= 1 ? sweep : null,
    updatedAt: senate?.forecast.updatedAt ?? house?.forecast.updatedAt ?? null,
    houseHistory: toPoints(house?.timeseries ?? []),
    senateHistory: toPoints(senate?.timeseries ?? []),
  };
}
